(7448179, 1178385, 100831, '<td valign="top">It was a top of 42 today here... yes, a beach would be nice. The saturated (bright) colors are pretty too.</td>', 'It was a top of 42 today here... yes, a beach would be nice. The saturated (bright) colors are pretty too.', '2016-04-05 19:51:42.000000', NULL, 1),
(7448180, 1178394, 100831, '<td valign="top">Very nicely done without making this just another picture of Tom Friedman art. Funny how he doesn''t look so tall from this (great) perspective. I like the b/w.</td>', 'Very nicely done without making this just another picture of Tom Friedman art. Funny how he doesn''t look so tall from this (great) perspective. I like the b/w.', '2016-04-05 19:51:46.000000', NULL, 1),
(7448181, 1178315, 100831, '<td valign="top">I like how the mountain top mimics the arcs of the bridge (almost).  Very well done overall, IMHO.</td>', 'I like how the mountain top mimics the arcs of the bridge (almost).  Very well done overall, IMHO.', '2016-04-05 19:52:54.000000', NULL, 1),
